oracle.code:
BEGIN
  UPDATE Course
  SET seats_available = seats_available - 1
  WHERE course_code = 'DB101' AND seats_available > 0;

  IF SQL%ROWCOUNT = 0 THEN
    RAISE_APPLICATION_ERROR(-20001, 'No seat available');
  END IF;

  INSERT INTO Enrolment (student_id, course_code, mark)
  VALUES (104, 'DB101', NULL);
  COMMIT;
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    RAISE;
END;
/

sqlserver.code:
SET XACT_ABORT ON;
BEGIN TRY
  BEGIN TRANSACTION;
  UPDATE Course
  SET seats_available = seats_available - 1
  WHERE course_code = 'DB101' AND seats_available > 0;

  IF @@ROWCOUNT = 0
    THROW 50001, 'No seat available', 1;

  INSERT INTO Enrolment (student_id, course_code, mark)
  VALUES (104, 'DB101', NULL);
  COMMIT TRANSACTION;
END TRY
BEGIN CATCH
  IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
  THROW;
END CATCH;

